36	  categoria_nome?: string;
37	}
38	
39	// ─── Constantes ─────────────────────────────────────────────────────────────
40	
41	export const MATCH_THRESHOLD = 0.72;
42	
43	// ─── Ghost Items ────────────────────────────────────────────────────────────
44	
45	/** Verifica se o item é "fantasma" (quantidade solicitada = 0). */
46	export function isGhostItem(item: AIProcessedItem): boolean {
47	  return item.requested === 0;
48	}
49	
50	// ─── Locked Items ───────────────────────────────────────────────────────────
51	
52	/** Verifica se o item está bloqueado (linkado ao catálogo master). */
53	export function isLockedItem(item: AIProcessedItem): boolean {
54	  return item.isLocked === true;
55	}
56	
57	// ─── Visual State ───────────────────────────────────────────────────────────
58	
59	export interface ItemVisualState {
60	  borderColor: string;
61	  bgColor: string;
62	  opacity: number;
63	  isGhost: boolean;
64	  isSeparated: boolean;
65	}
66	
67	/** Calcula o estado visual de um item na lista. */
68	export function getItemVisualState(item: AIProcessedItem): ItemVisualState {
69	  const isGhost = isGhostItem(item);
70	  const isSeparated = item.is_separated === true;
71	
72	  let borderColor = isSeparated ? 'border-green-500/50' : 'border-border/50';
73	  let bgColor = isSeparated ? 'bg-green-50/50 dark:bg-green-900/20' : 'bg-background/50';
74	
75	  if (isGhost) {
76	    borderColor = 'border-dashed border-muted';
77	    bgColor = 'bg-muted/30';
78	  }
79	
80	  const opacity = isGhost ? 0.6 : 1;
81	
82	  return { borderColor, bgColor, opacity, isGhost, isSeparated };
83	}
84	
85	// ─── Categoria Efetiva ──────────────────────────────────────────────────────
86	
87	/** Retorna a categoria efetiva do item (manual > auto-detectada > detecção). */
88	export function getItemEffectiveCategory(item: AIProcessedItem): string {
89	  return getEffectiveCategory(item.manualCategory, item.category, item.name);
90	}
91	
92	// ─── Criação de Itens ───────────────────────────────────────────────────────
93	
94	/** Cria um novo item vazio para adição manual. */
95	export function createNewItem(
96	  id: string,
97	  name?: string,
98	  category?: string
99	): AIProcessedItem {
100	  return {
101	    id,
102	    name: name || '',
103	    requested: 0,
104	    sent: '',
105	    observation: '',
106	    is_separated: false,
107	    separated_by: undefined,
108	    separated_at: undefined,
109	    category: category || 'Geral',
110	    manualCategory: category,
111	  };
112	}
113	
114	/** Cria um item a partir de um produto do catálogo master. */
115	export function createItemFromCatalog(
116	  id: string,
117	  product: CatalogProduct
118	): AIProcessedItem {
119	  const masterCategory = product.categoria_nome || detectCategory(product.nome);
120	  return {
121	    id,
122	    name: product.nome,
123	    requested: 0,
124	    sent: '',
125	    observation: '',
126	    category: masterCategory,
127	    manualCategory: masterCategory,
128	    matchedId: product.id.toString(),
129	    code: product.codigo_interno,
130	    isLocked: true,
131	    matchConfidence: 1,
132	  };
133	}
134	
135	// ─── Alias Map (aprendizado de match) ──────────────────────────────────────
136	
137	/** Mapa de alias → produto_id para match por aprendizado. */
138	export interface AliasEntry {
139	  produto_id: number;
140	  alias: string;
141	}
142	
143	// ─── Auto-Enrichment (Match com catálogo) ───────────────────────────────────
144	
145	export interface EnrichmentResult {
146	  /** Itens mantidos na lista principal (matched). */
147	  keptItems: AIProcessedItem[];
148	  /** Itens movidos para revisão (unmatched). */
149	  reviewItems: AIProcessedItem[];
150	  /** Se houve alguma mudança. */
151	  hasChanges: boolean;
152	  /** Aliases usados neste enriquecimento (para incrementar used_count). */
153	  usedAliasIds: number[];
154	}
155	
156	/**
157	 * Enriquece itens fazendo match com o catálogo de produtos.
158	 * Prioridade: 1) já locked → manter, 2) match estrito por nome,
159	 * 3) match por alias (aprendizado), 4) fuzzy similarity.
160	 * Sem match → vai para revisão.
161	 */
162	export function enrichItemsWithCatalog(
163	  items: AIProcessedItem[],
164	  catalog: CatalogProduct[],
165	  threshold: number = MATCH_THRESHOLD,
166	  aliases: AliasEntry[] = []
167	): EnrichmentResult {
168	  if (catalog.length === 0 || items.length === 0) {
169	    return { keptItems: [...items], reviewItems: [], hasChanges: false, usedAliasIds: [] };
170	  }
171	
172	  const normalize = (s: string) => s.toLowerCase().trim();
173	  const catalogById = new Map(catalog.map(p => [p.id, p]));
174	
175	  // Indexar aliases: alias normalizado → produto
176	  const aliasMap = new Map<string, CatalogProduct>();
177	  for (const a of aliases) {
178	    const prod = catalogById.get(a.produto_id);
179	    if (prod) aliasMap.set(normalize(a.alias), prod);
180	  }
181	
182	  let hasChanges = false;
183	  const keptItems: AIProcessedItem[] = [];
184	  const reviewItems: AIProcessedItem[] = [];
185	  const usedAliasIds: number[] = [];
186	
187	  for (const item of items) {
188	    // 1) Itens já locked/coded são mantidos
189	    if (item.code && item.isLocked && item.matchedId) {
190	      keptItems.push(item);
191	      continue;
192	    }
193	
194	    const itemNorm = normalize(item.name);
195	
196	    // 2) Match estrito por nome no catálogo
197	    let match = catalog.find(p => normalize(p.nome) === itemNorm);
198	    let bestScore = 1;
199	    let matchSource: 'exact' | 'alias' | 'fuzzy' = 'exact';
200	
201	    // 3) Match por alias (aprendizado) — se não houve match estrito
202	    if (!match) {
203	      const aliasMatch = aliasMap.get(itemNorm);
204	      if (aliasMatch) {
205	        match = aliasMatch;
206	        bestScore = 1;
207	        matchSource = 'alias';
208	        const aliasEntry = aliases.find(a => normalize(a.alias) === itemNorm);
209	        if (aliasEntry) usedAliasIds.push(aliasEntry.produto_id);
210	      }
211	    }
212	
213	    // 4) Match fuzzy se nenhum anterior achou
214	    if (!match) {
215	      let bestMatch: CatalogProduct | null = null;
216	      let bestSim = 0;
217	      for (const p of catalog) {
218	        const sim = similarity(item.name, p.nome);
219	        if (sim > bestSim) {
220	          bestSim = sim;
221	          bestMatch = p;
222	        }
223	      }
224	      if (bestMatch && bestSim >= threshold) {
225	        match = bestMatch;
226	        bestScore = bestSim;
227	        matchSource = 'fuzzy';
228	      }
229	    }
230	
231	    if (match) {
232	      hasChanges = true;
233	      keptItems.push({
234	        ...item,
235	        name: match.nome,
236	        code: match.codigo_interno,
237	        matchedId: match.id.toString(),
238	        category: match.categoria_nome || item.category,
239	        manualCategory: match.categoria_nome || item.manualCategory,
240	        isLocked: true,
241	        matchConfidence: bestScore,
242	        isLowConfidence: false,
243	        originalName: matchSource !== 'exact' ? item.name : undefined,
244	      });
245	    } else {
246	      hasChanges = true;
247	      reviewItems.push({
248	        ...item,
249	        isLowConfidence: true,
250	        originalName: item.name,
251	      });
252	    }
253	  }
254	
255	  return { keptItems, reviewItems, hasChanges, usedAliasIds };
256	}
257	
258	// ─── Validação de Submissão ─────────────────────────────────────────────────
259	
260	export interface SubmissionValidation {
261	  valid: boolean;
262	  hasLowConfidenceItems: boolean;
263	}
264	
265	/** Valida se a lista de itens pode ser submetida. */
266	export function validateItemsForSubmission(items: AIProcessedItem[]): SubmissionValidation {
267	  const hasLowConfidenceItems = items.some(i => i.isLowConfidence);
268	  return {
269	    valid: !hasLowConfidenceItems,
270	    hasLowConfidenceItems,
271	  };
272	}
273	
274	// ─── Agrupamento por Categoria ──────────────────────────────────────────────
275	
276	/**
277	 * Agrupa itens por categoria, preservando a ordem de aparição.
278	 * Categorias customizadas vazias são incluídas ao final.
279	 */
280	export function groupItemsByCategory(
281	  items: AIProcessedItem[],
282	  customCategories: string[] = []
283	): Map<string, AIProcessedItem[]> {
284	  const orderedCategories: string[] = [];
285	  const seen = new Set<string>();
286	
287	  // Categorias ordenadas pela primeira aparição nos itens
288	  items.forEach(it => {
289	    const cat = (it.category?.trim() || 'Geral');
290	    if (!seen.has(cat)) {
291	      seen.add(cat);
292	      orderedCategories.push(cat);
293	    }
294	  });
295	
296	  // Categorias customizadas ainda sem itens
297	  customCategories.forEach(cat => {
298	    const name = (cat || '').trim();
299	    if (name && !seen.has(name)) {
300	      seen.add(name);
301	      orderedCategories.push(name);
302	    }
303	  });
304	
305	  // Mapear itens por categoria
306	  const itemsByCategory = new Map<string, AIProcessedItem[]>();
307	  orderedCategories.forEach(cat => itemsByCategory.set(cat, []));
308	  items.forEach(it => {
309	    const cat = (it.category?.trim() || 'Geral');
310	    const arr = itemsByCategory.get(cat) || [];
311	    arr.push(it);
312	    itemsByCategory.set(cat, arr);
313	  });
314	
315	  return itemsByCategory;
316	}
317	
318	/** Calcula o total de quantidade solicitada por categoria. */
319	export function getCategoryTotalRequested(items: AIProcessedItem[]): number {
320	  return items.reduce((sum, it) => sum + (Number(it.requested) || 0), 0);
321	}
322	
323	// ─── Gerenciamento de Categorias ────────────────────────────────────────────
324	
325	/** Adiciona uma nova categoria à lista, evitando duplicatas. */
326	export function addCategory(
327	  existing: string[],
328	  newCategory: string
329	): string[] {
330	  const name = (newCategory || '').trim();
331	  if (!name) return existing;
332	  return Array.from(new Set([...existing, name]));
333	}
334	
335	/** Renomeia uma categoria em todos os itens. */
336	export function renameCategoryInItems(
337	  items: AIProcessedItem[],
338	  oldName: string,
339	  newName: string
340	): AIProcessedItem[] {
341	  const oldTrim = (oldName || '').trim();
342	  const newTrim = (newName || '').trim();
343	  if (!newTrim || oldTrim === newTrim) return items;
344	
345	  return items.map(i => {
346	    const cat = (i.category?.trim() || 'Geral');
347	    const man = (i.manualCategory || '').trim();
348	    if (cat === oldTrim || man === oldTrim) {
349	      return { ...i, category: newTrim, manualCategory: newTrim };
350	    }
351	    return i;
352	  });
353	}
354	
355	/** Verifica se uma categoria pode ser removida (não pode ter itens). */
356	export function canRemoveCategory(
357	  items: AIProcessedItem[],
358	  categoryName: string
359	): boolean {
360	  const trimmed = (categoryName || '').trim();
361	  if (!trimmed) return false;
362	  return !items.some(i => {
363	    const cat = (i.category?.trim() || 'Geral');
364	    const man = (i.manualCategory || '').trim();
365	    return cat === trimmed || man === trimmed;
366	  });
367	}
368	
369	/** Remove uma categoria da lista. */
370	export function removeCategory(
371	  existing: string[],
372	  categoryName: string
373	): string[] {
374	  const trimmed = (categoryName || '').trim();
375	  if (!trimmed) return existing;
376	  return existing.filter(c => c !== trimmed);
377	}
378	
379	// ─── Formatação ─────────────────────────────────────────────────────────────
380	
381	/** Formata data no padrão brasileiro (dd/MM/yyyy HH:mm), timezone São Paulo. */
382	export function formatDateTimeBr(value?: string | null): string {
383	  if (!value) return '';
384	  const d = new Date(value);
385	  if (isNaN(d.getTime())) return '';
386	  return new Intl.DateTimeFormat('pt-BR', {
387	    day: '2-digit', month: '2-digit', year: 'numeric',
388	    hour: '2-digit', minute: '2-digit', hour12: false,
389	    timeZone: 'America/Sao_Paulo'
390	  }).format(d);
391	}
392	
393	/** Formata elapsed time em MM:SS. */
394	export function formatElapsed(seconds: number): string {
395	  const s = Math.max(0, Number(seconds) || 0);
396	  const mm = String(Math.floor(s / 60)).padStart(2, '0');
397	  const ss = String(s % 60).padStart(2, '0');
398	  return `${mm}:${ss}`;
399	}
400	
401	/** Extrai timestamp de enfileiramento de uma requisição. */
402	export function getQueueTimestamp(
403	  req: Record<string, unknown> | null | undefined,
404	  formatter: (v?: string | null) => string = formatDateTimeBr
405	): string {
406	  if (!req) return '—';
407	  const v = (req.enqueued_at ?? req.enqueuedAt ?? req.created_at ?? req.createdAt ?? null) as string | null;
408	  return formatter(v) || '—';
409	}
410	
411	// ─── Resolução de Match ─────────────────────────────────────────────────────
412	
413	/** Resolve um item não-matched selecionando um produto do catálogo. */
414	export function resolveUnmatchedItem(
415	  item: AIProcessedItem,
416	  product: CatalogProduct
417	): AIProcessedItem {
418	  return {
419	    ...item,
420	    matchedId: product.id.toString(),
421	    name: product.nome,
422	    code: product.codigo_interno,
423	    isLocked: true,
424	    isLowConfidence: false,
425	  };
426	}
427	
428	/** Merge de itens deduplicados (para a fila de revisão). */
429	export function deduplicateReviewItems(
430	  existing: AIProcessedItem[],
431	  newItems: AIProcessedItem[]
432	): AIProcessedItem[] {
433	  const combined = [...existing, ...newItems];
434	  return Array.from(new Map(combined.map(item => [item.id, item])).values());
435	}
436	
437	/** Calcula confiança formatada para exibição. */
438	export function formatConfidencePercent(confidence?: number): string {
439	  return confidence ? (confidence * 100).toFixed(0) : '0';
440	}
441	
442	/** Gera texto de banner de pendências. */
443	export function getUnmatchedBannerText(count: number): string {
444	  if (count === 0) return '';
445	  return count === 1
446	    ? '1 item precisa de revisão'
447	    : `${count} itens precisam de revisão`;
448	}
