/**
 * Lógica pura extraída de Requisicao.tsx para testabilidade.
 * Funções sem dependência de React, Supabase ou side-effects.
 */

import { similarity } from '@/shared/lib/stringUtils';
import { detectCategory, getEffectiveCategory } from '@/shared/lib/category';

// ─── Tipos ──────────────────────────────────────────────────────────────────

export interface AIProcessedItem {
  name: string;
  requested: number;
  sent: string;
  observation?: string;
  id: string;
  matchedId?: string;
  originalName?: string;
  matchConfidence?: number;
  isLowConfidence?: boolean;
  code?: string;
  isLocked?: boolean;
  is_separated?: boolean;
  separated_by?: string;
  separated_at?: string;
  category?: string;
  manualCategory?: string;
  ai_reasoning?: string;
}

export interface CatalogProduct {
  id: number;
  nome: string;
  unidade_medida?: string;
  codigo_interno?: string;
  categoria_nome?: string;
}

// ─── Constantes ─────────────────────────────────────────────────────────────

export const MATCH_THRESHOLD = 0.72;

// ─── Ghost Items ────────────────────────────────────────────────────────────

/** Verifica se o item é "fantasma" (quantidade solicitada = 0). */
export function isGhostItem(item: AIProcessedItem): boolean {
  return item.requested === 0;
}

// ─── Locked Items ───────────────────────────────────────────────────────────

/** Verifica se o item está bloqueado (linkado ao catálogo master). */
export function isLockedItem(item: AIProcessedItem): boolean {
  return item.isLocked === true;
}

// ─── Visual State ───────────────────────────────────────────────────────────

export interface ItemVisualState {
  borderColor: string;
  bgColor: string;
  opacity: number;
  isGhost: boolean;
  isSeparated: boolean;
}

/** Calcula o estado visual de um item na lista. */
export function getItemVisualState(item: AIProcessedItem): ItemVisualState {
  const isGhost = isGhostItem(item);
  const isSeparated = item.is_separated === true;

  let borderColor = isSeparated ? 'border-green-500/50' : 'border-border/50';
  let bgColor = isSeparated ? 'bg-green-50/50 dark:bg-green-900/20' : 'bg-background/50';

  if (isGhost) {
    borderColor = 'border-dashed border-muted';
    bgColor = 'bg-muted/30';
  }

  const opacity = isGhost ? 0.6 : 1;

  return { borderColor, bgColor, opacity, isGhost, isSeparated };
}

// ─── Categoria Efetiva ──────────────────────────────────────────────────────

/** Retorna a categoria efetiva do item (manual > auto-detectada > detecção). */
export function getItemEffectiveCategory(item: AIProcessedItem): string {
  return getEffectiveCategory(item.manualCategory, item.category, item.name);
}

// ─── Criação de Itens ───────────────────────────────────────────────────────

/** Cria um novo item vazio para adição manual. */
export function createNewItem(
  id: string,
  name?: string,
  category?: string
): AIProcessedItem {
  return {
    id,
    name: name || '',
    requested: 0,
    sent: '',
    observation: '',
    is_separated: false,
    separated_by: undefined,
    separated_at: undefined,
    category: category || 'Geral',
    manualCategory: category,
  };
}

/** Cria um item a partir de um produto do catálogo master. */
export function createItemFromCatalog(
  id: string,
  product: CatalogProduct
): AIProcessedItem {
  const masterCategory = product.categoria_nome || detectCategory(product.nome);
  return {
    id,
    name: product.nome,
    requested: 0,
    sent: '',
    observation: '',
    category: masterCategory,
    manualCategory: masterCategory,
    matchedId: product.id.toString(),
    code: product.codigo_interno,
    isLocked: true,
    matchConfidence: 1,
  };
}

// ─── Alias Map (aprendizado de match) ──────────────────────────────────────

/** Mapa de alias → produto_id para match por aprendizado. */
export interface AliasEntry {
  produto_id: number;
  alias: string;
}

// ─── Auto-Enrichment (Match com catálogo) ───────────────────────────────────

export interface EnrichmentResult {
  /** Itens mantidos na lista principal (matched). */
  keptItems: AIProcessedItem[];
  /** Itens movidos para revisão (unmatched). */
  reviewItems: AIProcessedItem[];
  /** Se houve alguma mudança. */
  hasChanges: boolean;
  /** Aliases usados neste enriquecimento (para incrementar used_count). */
  usedAliasIds: number[];
}

/**
 * Enriquece itens fazendo match com o catálogo de produtos.
 * Prioridade: 1) já locked → manter, 2) match estrito por nome,
 * 3) match por alias (aprendizado), 4) fuzzy similarity.
 * Sem match → vai para revisão.
 */
export function enrichItemsWithCatalog(
  items: AIProcessedItem[],
  catalog: CatalogProduct[],
  threshold: number = MATCH_THRESHOLD,
  aliases: AliasEntry[] = []
): EnrichmentResult {
  if (catalog.length === 0 || items.length === 0) {
    return { keptItems: [...items], reviewItems: [], hasChanges: false, usedAliasIds: [] };
  }

  const normalize = (s: string) => s.toLowerCase().trim();
  const catalogById = new Map(catalog.map(p => [p.id, p]));

  // Indexar aliases: alias normalizado → produto
  const aliasMap = new Map<string, CatalogProduct>();
  for (const a of aliases) {
    const prod = catalogById.get(a.produto_id);
    if (prod) aliasMap.set(normalize(a.alias), prod);
  }

  let hasChanges = false;
  const keptItems: AIProcessedItem[] = [];
  const reviewItems: AIProcessedItem[] = [];
  const usedAliasIds: number[] = [];

  for (const item of items) {
    // 1) Itens já locked/coded são mantidos
    if (item.code && item.isLocked && item.matchedId) {
      keptItems.push(item);
      continue;
    }

    const itemNorm = normalize(item.name);

    // 2) Match estrito por nome no catálogo
    let match = catalog.find(p => normalize(p.nome) === itemNorm);
    let bestScore = 1;
    let matchSource: 'exact' | 'alias' | 'fuzzy' = 'exact';

    // 3) Match por alias (aprendizado) — se não houve match estrito
    if (!match) {
      const aliasMatch = aliasMap.get(itemNorm);
      if (aliasMatch) {
        match = aliasMatch;
        bestScore = 1;
        matchSource = 'alias';
        const aliasEntry = aliases.find(a => normalize(a.alias) === itemNorm);
        if (aliasEntry) usedAliasIds.push(aliasEntry.produto_id);
      }
    }

    // 4) Match fuzzy se nenhum anterior achou
    if (!match) {
      let bestMatch: CatalogProduct | null = null;
      let bestSim = 0;
      for (const p of catalog) {
        const sim = similarity(item.name, p.nome);
        if (sim > bestSim) {
          bestSim = sim;
          bestMatch = p;
        }
      }
      if (bestMatch && bestSim >= threshold) {
        match = bestMatch;
        bestScore = bestSim;
        matchSource = 'fuzzy';
      }
    }

    if (match) {
      hasChanges = true;
      keptItems.push({
        ...item,
        name: match.nome,
        code: match.codigo_interno,
        matchedId: match.id.toString(),
        category: match.categoria_nome || item.category,
        manualCategory: match.categoria_nome || item.manualCategory,
        isLocked: true,
        matchConfidence: bestScore,
        isLowConfidence: false,
        originalName: matchSource !== 'exact' ? item.name : undefined,
      });
    } else {
      hasChanges = true;
      reviewItems.push({
        ...item,
        isLowConfidence: true,
        originalName: item.name,
      });
    }
  }

  return { keptItems, reviewItems, hasChanges, usedAliasIds };
}

// ─── Validação de Submissão ─────────────────────────────────────────────────

export interface SubmissionValidation {
  valid: boolean;
  hasLowConfidenceItems: boolean;
}

/** Valida se a lista de itens pode ser submetida. */
export function validateItemsForSubmission(items: AIProcessedItem[]): SubmissionValidation {
  const hasLowConfidenceItems = items.some(i => i.isLowConfidence);
  return {
    valid: !hasLowConfidenceItems,
    hasLowConfidenceItems,
  };
}

// ─── Agrupamento por Categoria ──────────────────────────────────────────────

/**
 * Agrupa itens por categoria, preservando a ordem de aparição.
 * Categorias customizadas vazias são incluídas ao final.
 */
export function groupItemsByCategory(
  items: AIProcessedItem[],
  customCategories: string[] = []
): Map<string, AIProcessedItem[]> {
  const orderedCategories: string[] = [];
  const seen = new Set<string>();

  // Categorias ordenadas pela primeira aparição nos itens
  items.forEach(it => {
    const cat = (it.category?.trim() || 'Geral');
    if (!seen.has(cat)) {
      seen.add(cat);
      orderedCategories.push(cat);
    }
  });

  // Categorias customizadas ainda sem itens
  customCategories.forEach(cat => {
    const name = (cat || '').trim();
    if (name && !seen.has(name)) {
      seen.add(name);
      orderedCategories.push(name);
    }
  });

  // Mapear itens por categoria
  const itemsByCategory = new Map<string, AIProcessedItem[]>();
  orderedCategories.forEach(cat => itemsByCategory.set(cat, []));
  items.forEach(it => {
    const cat = (it.category?.trim() || 'Geral');
    const arr = itemsByCategory.get(cat) || [];
    arr.push(it);
    itemsByCategory.set(cat, arr);
  });

  return itemsByCategory;
}

/** Calcula o total de quantidade solicitada por categoria. */
export function getCategoryTotalRequested(items: AIProcessedItem[]): number {
  return items.reduce((sum, it) => sum + (Number(it.requested) || 0), 0);
}

// ─── Gerenciamento de Categorias ────────────────────────────────────────────

/** Adiciona uma nova categoria à lista, evitando duplicatas. */
export function addCategory(
  existing: string[],
  newCategory: string
): string[] {
  const name = (newCategory || '').trim();
  if (!name) return existing;
  return Array.from(new Set([...existing, name]));
}

/** Renomeia uma categoria em todos os itens. */
export function renameCategoryInItems(
  items: AIProcessedItem[],
  oldName: string,
  newName: string
): AIProcessedItem[] {
  const oldTrim = (oldName || '').trim();
  const newTrim = (newName || '').trim();
  if (!newTrim || oldTrim === newTrim) return items;

  return items.map(i => {
    const cat = (i.category?.trim() || 'Geral');
    const man = (i.manualCategory || '').trim();
    if (cat === oldTrim || man === oldTrim) {
      return { ...i, category: newTrim, manualCategory: newTrim };
    }
    return i;
  });
}

/** Verifica se uma categoria pode ser removida (não pode ter itens). */
export function canRemoveCategory(
  items: AIProcessedItem[],
  categoryName: string
): boolean {
  const trimmed = (categoryName || '').trim();
  if (!trimmed) return false;
  return !items.some(i => {
    const cat = (i.category?.trim() || 'Geral');
    const man = (i.manualCategory || '').trim();
    return cat === trimmed || man === trimmed;
  });
}

/** Remove uma categoria da lista. */
export function removeCategory(
  existing: string[],
  categoryName: string
): string[] {
  const trimmed = (categoryName || '').trim();
  if (!trimmed) return existing;
  return existing.filter(c => c !== trimmed);
}

// ─── Formatação ─────────────────────────────────────────────────────────────

/** Formata data no padrão brasileiro (dd/MM/yyyy HH:mm), timezone São Paulo. */
export function formatDateTimeBr(value?: string | null): string {
  if (!value) return '';
  const d = new Date(value);
  if (isNaN(d.getTime())) return '';
  return new Intl.DateTimeFormat('pt-BR', {
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit', hour12: false,
    timeZone: 'America/Sao_Paulo'
  }).format(d);
}

/** Formata elapsed time em MM:SS. */
export function formatElapsed(seconds: number): string {
  const s = Math.max(0, Number(seconds) || 0);
  const mm = String(Math.floor(s / 60)).padStart(2, '0');
  const ss = String(s % 60).padStart(2, '0');
  return `${mm}:${ss}`;
}

/** Extrai timestamp de enfileiramento de uma requisição. */
export function getQueueTimestamp(
  req: Record<string, unknown> | null | undefined,
  formatter: (v?: string | null) => string = formatDateTimeBr
): string {
  if (!req) return '—';
  const v = (req.enqueued_at ?? req.enqueuedAt ?? req.created_at ?? req.createdAt ?? null) as string | null;
  return formatter(v) || '—';
}

// ─── Resolução de Match ─────────────────────────────────────────────────────

/** Resolve um item não-matched selecionando um produto do catálogo. */
export function resolveUnmatchedItem(
  item: AIProcessedItem,
  product: CatalogProduct
): AIProcessedItem {
  return {
    ...item,
    matchedId: product.id.toString(),
    name: product.nome,
    code: product.codigo_interno,
    isLocked: true,
    isLowConfidence: false,
  };
}

/** Merge de itens deduplicados (para a fila de revisão). */
export function deduplicateReviewItems(
  existing: AIProcessedItem[],
  newItems: AIProcessedItem[]
): AIProcessedItem[] {
  const combined = [...existing, ...newItems];
  return Array.from(new Map(combined.map(item => [item.id, item])).values());
}

/** Calcula confiança formatada para exibição. */
export function formatConfidencePercent(confidence?: number): string {
  return confidence ? (confidence * 100).toFixed(0) : '0';
}

/** Gera texto de banner de pendências. */
export function getUnmatchedBannerText(count: number): string {
  if (count === 0) return '';
  return count === 1
    ? '1 item precisa de revisão'
    : `${count} itens precisam de revisão`;
}

