/**
 * @module stringUtils
 *
 * Funções de normalização e comparação de strings, usadas para
 * correspondência fuzzy de nomes de produtos/itens.
 */

/**
 * Normaliza um nome para comparação case-insensitive e sem acentos.
 *
 * Remove diacríticos (NFD), caracteres especiais e espaços extras.
 *
 * @param s - String a ser normalizada.
 * @returns String em lowercase, sem acentos, apenas `[a-z0-9\s]`.
 *
 * @example
 * ```ts
 * normalizeName("Pão de Mel (100g)"); // "pao de mel 100g"
 * ```
 */
export const normalizeName = (s: string): string => {
  return s
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
};

/**
 * Calcula a distância de Levenshtein (edição) entre duas strings.
 *
 * @param a - Primeira string.
 * @param b - Segunda string.
 * @returns Número mínimo de inserções, remoções ou substituições para transformar `a` em `b`.
 *
 * @example
 * ```ts
 * levenshtein("gato", "rato"); // 1
 * ```
 */
export const levenshtein = (a: string, b: string): number => {
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,
        dp[i][j - 1] + 1,
        dp[i - 1][j - 1] + cost,
      );
    }
  }
  return dp[m][n];
};

/**
 * Retorna um score de similaridade entre 0 e 1 para duas strings.
 *
 * Utiliza Levenshtein normalizado sobre os nomes após {@link normalizeName},
 * com bônus de +0.1 quando uma string é substring da outra.
 *
 * @param a - Primeira string (original, não normalizada).
 * @param b - Segunda string (original, não normalizada).
 * @returns Score de 0 (completamente diferentes) a 1 (idênticos).
 *
 * @example
 * ```ts
 * similarity("Bolo de chocolate", "Bolo Chocolate"); // ~0.85
 * similarity("Pão", "Queijo");                       // ~0.0
 * ```
 */
export const similarity = (a: string, b: string): number => {
  const na = normalizeName(a);
  const nb = normalizeName(b);
  if (!na || !nb) return 0;
  const dist = levenshtein(na, nb);
  const maxLen = Math.max(na.length, nb.length);
  const baseScore = 1 - dist / maxLen;
  const substrBonus = (na.includes(nb) || nb.includes(na)) ? 0.1 : 0;
  return Math.max(0, Math.min(1, baseScore + substrBonus));
};

/**
 * @module category
 *
 * Detecção, normalização e validação de categorias de produtos.
 * Usado pela produção diária, requisições e separação (picking).
 */

/** Categorias padrão do sistema, em ordem de prioridade na UI. */
export const DEFAULT_CATEGORIES = [
  'GELATOS',
  'BOLO POTE',
  'FATIAS/TARTELETES',
  'MINIS',
  'OUTROS',
  'Geral',
] as const;

/** Tipo literal com todas as categorias padrão. */
export type DefaultCategory = (typeof DEFAULT_CATEGORIES)[number];

/**
 * Detecta automaticamente a categoria de um produto pelo nome usando regras de regex.
 *
 * Ordem de precedência: GELATOS → BOLO POTE → FATIAS/TARTELETES → MINIS → OUTROS.
 *
 * @param rawName - Nome bruto do produto.
 * @returns Nome da categoria detectada.
 *
 * @example
 * ```ts
 * detectCategory("Gelato Pistache 500ml"); // "GELATOS"
 * detectCategory("Mini Brownie");          // "MINIS"
 * detectCategory("Salgado Especial");      // "OUTROS"
 * ```
 */
export const detectCategory = (rawName: string): string => {
  const name = (rawName || '').toLowerCase();
  const has = (p: RegExp) => p.test(name);
  if (has(/\bgelato\b|\bsorvete\b/)) return 'GELATOS';
  if (has(/\bbolo\b/) || has(/\bpote\b/) || has(/\bbolo no pote\b/)) return 'BOLO POTE';
  if (has(/\bfatia\b|\bfatias\b|\btartelete\b|\btarteletes\b/)) return 'FATIAS/TARTELETES';
  if (has(/^mini\b/)) return 'MINIS';
  if (
    has(/\bfranui\b|\bpão de mel\b|\bbrigadeiro\b|\bpistache\b|\bbrownie\b|\bprestígio\b|\blimão\b|\bcafé\b/) &&
    !has(/\bbolo\b|\bfatia\b|\btartelete\b|\bgelato\b/)
  ) {
    return 'MINIS';
  }
  return 'OUTROS';
};

/**
 * Retorna a categoria efetiva para um item, priorizando a seleção manual.
 *
 * Cascata: manual → auto-detectada → detectada pelo nome → `"Geral"`.
 *
 * @param manualCategory - Categoria definida manualmente pelo usuário.
 * @param autoCategory   - Categoria detectada automaticamente e persistida.
 * @param itemName       - Nome do item (usado como último recurso via {@link detectCategory}).
 * @returns A categoria efetiva.
 */
export const getEffectiveCategory = (
  manualCategory?: string | null,
  autoCategory?: string | null,
  itemName?: string,
): string => {
  if (manualCategory && manualCategory.trim()) return manualCategory.trim();
  if (autoCategory && autoCategory.trim()) return autoCategory.trim();
  if (itemName) return detectCategory(itemName);
  return 'Geral';
};

/**
 * Verifica se um item possui categoria manual definida (que deve ser preservada em edições).
 *
 * @param manualCategory - Valor da categoria manual.
 * @returns `true` se houver uma categoria manual não-vazia.
 */
export const shouldPreserveCategory = (manualCategory?: string | null): boolean => {
  return !!(manualCategory && manualCategory.trim());
};

/**
 * Valida se o nome de uma categoria é aceitável (não vazio, máx. 50 caracteres).
 *
 * @param name - Nome da categoria a validar.
 */
export const isValidCategoryName = (name: string): boolean => {
  const trimmed = name.trim();
  return trimmed.length > 0 && trimmed.length <= 50;
};

/**
 * Normaliza o nome de uma categoria para uppercase e sem espaços extras.
 *
 * @param name - Nome original.
 * @returns Nome normalizado em maiúsculas.
 */
export const normalizeCategoryName = (name: string): string => {
  return name.trim().toUpperCase();
};

