const parseNumber = (value?: string | null) => {
  if (!value) return 0;
  const m = value.match(/[0-9]+([.,][0-9]+)?/);
  if (!m) return 0;
  const n = parseFloat(m[0].replace(',', '.'));
  return isNaN(n) ? 0 : n;
};

export const RequisicaoDetailsModal = ({
  isOpen,
  onClose,
  requisicao,
}: Props) => {
  const isMobile = useIsMobile();
  const [loading, setLoading] = useState(false);
  const [itens, setItens] = useState<RequisicaoItemRow[]>([]);

  useEffect(() => {
    const load = async () => {
      if (!isOpen || !requisicao) return;
      setLoading(true);
      const { data, error } = await supabase
        .from('requisicoes_itens')
        .select(
          'id, nome_produto, quantidade_solicitada, quantidade_enviada, observacao, ordem, lote, validade',
        )
        .eq('requisicao_id', requisicao.id)
        .order('ordem', { ascending: true });
      if (!error) setItens((data || []) as RequisicaoItemRow[]);
      setLoading(false);
    };
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, requisicao?.id]);

  const totalPedida = useMemo(
    () =>
      itens.reduce(
        (acc, it) => acc + (Number(it.quantidade_solicitada) || 0),
        0,
      ),
    [itens],
  );
  const totalEntregue = useMemo(
    () =>
      itens.reduce((acc, it) => acc + parseNumber(it.quantidade_enviada), 0),
    [itens],
  );

  const formatDateBR = (iso?: string | null) => {
    if (!iso) return '-';
    const [y, m, d] = iso.split('-');
    return `${d}/${m}/${y}`;
  };

  const printSelected = () => {
    if (!requisicao) return;

    const orderDateFormatted = formatDateBR(requisicao.data_pedido);
    const receivedDateFormatted = formatDateBR(requisicao.data_recebimento);

    const printContent = `
      <!DOCTYPE html>
      <html>
      <head>
        <title>Requisição Fábrica</title>
        <style>
          @page { margin: 15mm; size: A4; }
          * { margin: 0; padding: 0; box-sizing: border-box; }
          body { font-family: Arial, sans-serif; font-size: 11px; line-height: 1.2; }
          .header { background-color: #4CAF50; color: white; text-align: center; padding: 8px; font-weight: bold; font-size: 14px; }
          .header-title { letter-spacing: 0.5px; }
          .info-section { border: 1px solid #333; border-top: none; }
          .info-row { display: flex; border-bottom: 1px solid #333; min-height: 25px; }
          .info-row:last-child { border-bottom: none; }
          .info-cell { padding: 4px 8px; border-right: 1px solid #333; display: flex; align-items: center; background-color: #f5f5f5; }
          .info-cell:last-child { border-right: none; }
          .info-cell.value { background-color: white; font-weight: bold; }
          .products-header { background-color: #4CAF50; color: white; display: flex; font-weight: bold; border: 1px solid #333; margin-top: 10px; }
          .products-header div { padding: 6px 4px; border-right: 1px solid #333; text-align: center; font-size: 10px; }
          .products-header div:last-child { border-right: none; }
          .product-row { display: flex; border: 1px solid #333; border-top: none; min-height: 22px; }
          .product-cell { padding: 3px 6px; border-right: 1px solid #333; display: flex; align-items: center; font-size: 10px; }
          .product-cell:last-child { border-right: none; }
          .product-name { flex: 2; text-transform: uppercase; font-weight: bold; }
          .quantity-cell { flex: 0.6; text-align: center; justify-content: center; }
          .obs-cell { flex: 1.5; }
          .check-cell { flex: 0.6; text-align: center; justify-content: center; }
          @media print { body { -webkit-print-color-adjust: exact; } }
        </style>
      </head>
      <body>
        <div class="header">
          <span class="header-title">MOMMA DOCES SAUDÁVEIS</span>
          ${requisicao.subtitle ? `<br/><span style="font-size: 12px; font-weight: normal;">${requisicao.subtitle}</span>` : ''}
        </div>
        <div class="info-section">
          <div class="info-row">
            <div class="info-cell" style="flex: 1;">SOLICITANTE:</div>
