          </div>
          <div class="info-row">
            <div class="info-cell" style="flex: 1;">LOJA SOLICITANTE:</div>
            <div class="info-cell value" style="flex: 1;">${getStoreLabel(requisicao.loja_solicitante)}</div>
            <div class="info-cell" style="flex: 1;">LOCAL DE PREPARO:</div>
            <div class="info-cell value" style="flex: 1;">Fábrica</div>
          </div>
          <div class="info-row">
            <div class="info-cell" style="flex: 1;">DATA DO PEDIDO:</div>
            <div class="info-cell value" style="flex: 1;">${orderDateFormatted}</div>
            <div class="info-cell" style="flex: 1;">DATA RECEBIDO:</div>
            <div class="info-cell value" style="flex: 1;">${receivedDateFormatted}</div>
          </div>
        </div>
        <div class="products-header">
          <div class="product-name">PRODUTOS</div>
          <div class="quantity-cell">QUANT PEDIDOS</div>
          <div class="quantity-cell">QUANT ENTREGUE</div>
          <div class="obs-cell">SITUAÇÃO DO PEDIDO</div>
          <div class="quantity-cell">LOTE</div>
          <div class="quantity-cell">VAL.</div>
          <div class="obs-cell">OBSERVAÇÕES</div>
        </div>
        ${itens
          .map(
            (it) => `
          <div class="product-row">
            <div class="product-cell product-name">${(it.nome_produto || '').toUpperCase()}</div>
            <div class="product-cell quantity-cell">${it.quantidade_solicitada ?? ''}</div>
            <div class="product-cell quantity-cell">${it.quantidade_enviada ?? ''}</div>
            <div class="product-cell obs-cell"></div>
            <div class="product-cell quantity-cell">${it.lote || ''}</div>
            <div class="product-cell quantity-cell">${it.validade || ''}</div>
            <div class="product-cell obs-cell">${it.observacao ?? ''}</div>
          </div>
        `,
          )
          .join('')}
      </body>
      </html>
    `;

    printHTML(printContent, { title: `Requisição Fábrica` });
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent data-mia-modal="detalhes-da-requisi-o"
        className={`${isMobile ? 'w-[95vw] h-[95vh] max-w-none max-h-none p-3' : 'sm:max-w-5xl max-h-[90vh]'} overflow-y-auto`}
      >
        <DialogHeader className={isMobile ? 'pb-2' : ''}>
          <DialogTitle
            className={`flex items-center justify-between ${isMobile ? 'text-lg' : ''}`}
          >
            <div className="flex items-center gap-2 min-w-0">
              <span className={`${isMobile ? 'text-sm' : ''} truncate`}>
                Detalhes da Requisição
              </span>
            </div>
            <Button data-mia-action="on-close"
              variant="ghost"
              size={isMobile ? 'sm' : 'sm'}
              onClick={onClose}
              className="flex-shrink-0"
            >
              <X className="h-4 w-4" />
            </Button>
          </DialogTitle>
          {!isMobile && (
            <DialogDescription>
              Itens, quantidades pedidas e entregues
            </DialogDescription>
          )}
        </DialogHeader>

        {requisicao && (
          <div className="space-y-4">
            <Card>
              <CardHeader className={isMobile ? 'pb-2' : 'pb-4'}>
                <CardTitle className="flex flex-col gap-1">
                  <div className="flex items-center gap-2">
                    <span className="truncate">{requisicao.nome}</span>
                  </div>
                  {requisicao.subtitle && (
                    <div className="text-sm font-normal text-muted-foreground">
                      {requisicao.subtitle}
                    </div>
                  )}
                </CardTitle>
                <CardDescription>
                  <div
                    className={`grid ${isMobile ? 'grid-cols-1 gap-1' : 'grid-cols-2 gap-2'}`}
                  >
                    <div>
                      <span className="text-muted-foreground">Loja:</span>{' '}
                      {getStoreLabel(requisicao.loja_solicitante)}
                    </div>
                    <div>
                      <span className="text-muted-foreground">
                        Solicitante:
                      </span>{' '}
                      {requisicao.solicitante || '-'}
                    </div>
                    <div>
                      <span className="text-muted-foreground">Pedido:</span>{' '}
                      {formatDateBR(requisicao.data_pedido)}
                    </div>
                    <div>
                      <span className="text-muted-foreground">Recebido:</span>{' '}
                      {formatDateBR(requisicao.data_recebimento)}
                    </div>
                  </div>
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div
                  className={`flex ${isMobile ? 'flex-col gap-2' : 'items-center justify-between'}`}
                >
                  <div className="flex items-center gap-2">
                    <Badge variant="outline">Itens: {itens.length}</Badge>
                    <Badge variant="outline">Total Pedida: {totalPedida}</Badge>
                    <Badge variant="outline">
                      Total Entregue: {totalEntregue}
                    </Badge>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button data-mia-action="print-selected"
