      .map((item, index) => {
        const nome = String(item.name || '').trim();
        if (!nome) return null;
        const solicitadaRaw = item.requested;
        const solicitada = Number.isFinite(Number(solicitadaRaw)) ? Number(solicitadaRaw) : 0;
        const enviada = String(item.sent ?? '').trim();
        const obs = String(item.observation || '');
        const ordem = Number.isFinite(index) ? index : 0;
        const categoriaEfetiva = getEffectiveCategory(item.manualCategory, item.category, nome) || detectCategory(nome);
        return {
          nome_produto: nome,
          quantidade_solicitada: solicitada,
          quantidade_enviada: enviada,
          observacao: obs,
          ordem,
          category: categoriaEfetiva,
          produto_id: item.matchedId ? Number(item.matchedId) : null,
          codigo_interno: item.code || null,
          // RPC faz COALESCE pra 'cx' quando vazio.
          unidade_medida: item.unidade_medida || null,
        };
      })
      .filter((v) => v !== null);

    if (!itensSanitizados || itensSanitizados.length === 0) {
      toast.error('Nenhum item válido para salvar');
      return;
    }

    const { data: newId, error: rpcError } = await (supabase as any).rpc('save_requisicao_and_items', {
      p_nome: listName,
      p_solicitante: requesterName,
      p_preparador: preparerName,
      p_loja_solicitante: lojaSolicitante,
      p_loja_preparadora: lojaPreparadora,
      p_data_pedido: orderDateToSave,
      p_data_recebimento: receivedDateToSave || null,
      p_status: 'em_fila',
      p_itens: itensSanitizados,
      p_existing_id: currentRequisicaoId ? Number(currentRequisicaoId) : null,
      p_subtitle: requisitionSubtitle
    });

    if (rpcError) {
      handleError(rpcError, { domain: 'requisicoes', operation: 'salvarRequisicaoRpc', showToast: false });
      const msg = (rpcError as any)?.message || 'Erro desconhecido';
      const det = (rpcError as any)?.details || '';
      const code = (rpcError as any)?.code || '';
      const hint = (rpcError as any)?.hint || '';
      wideError('requisicao.rpc_erro_detalhes', 'Detalhes do erro RPC', { domain: 'requisicoes', attributes: { message: msg, code, details: det, hint } });
      toast.error(`Erro ao salvar requisição${code ? ` (${code})` : ''}: ${msg}`);
      return;
    }

    if (newId) {
      setCurrentRequisicaoId(String(newId));
      const updates = (itensSanitizados as any[]).map((it) => ({ nome_produto: it.nome_produto, category: it.category }));
      for (const u of updates) {
        await (supabase as any).from('requisicoes_itens').update({ category: u.category }).eq('requisicao_id', Number(newId)).eq('nome_produto', u.nome_produto);
      }
    }

    await loadHistoryFromDatabase();
    toast.success(`Requisição "${listName}" ${currentRequisicaoId ? 'atualizada' : 'salva'} e enviada para a fila`);
    if (isSessionMode) {
      exitSession();
      setIsSessionMode(false);
      setCurrentSessionId(null);
    }
  } catch (error) {
    handleError(error, { domain: 'requisicoes', operation: 'salvarListaRpc', showToast: false });
    toast.error('Erro ao salvar lista no histórico');
  } finally {
    setIsSavingList(false);
  }
};

