// Ir para etapa de entrega
const goToDeliveryStep = () => {
  // Preencher solicitante com nome do usuário atual
  if (userProfile?.nome && !requesterName) {
    setRequesterName(userProfile.nome);
  }
  // Iniciar transição suave
  setTransitionDirection('forward');
  setIsTransitioning(true);
  setTimeout(() => {
    setIsDeliveryStep(true);
    setIsTransitioning(false);
  }, 300); // Duração da animação
};

// Enviar pedido diretamente para a fila
const sendCurrentListToQueue = async () => {
  if (isSubmitting) return;
  setIsSubmitting(true);
  try {
  if (!requisitionSubtitle.trim()) {
    toast.error('Informe o tipo da requisição (Subtítulo)');
    return;
  }

  // VALIDATION: Strict check for unmatched AI items
  if (allItems.some(i => i.isLowConfidence)) {
    toast.warning("Existem itens pendentes de revisão. Por favor, resolva as inconsistências antes de enviar.");
    setIsMatchModalOpen(true);
    return;
  }

  // Fluxo de sessão ativa: finalizar e já marcar como em_fila
  if (isSessionMode) {
    if (!currentSessionId) {
      toast.error('Nenhuma sessão ativa encontrada');
      return;
    }

    const normalizedRequesterValue = normalizeStoreName(storeRequester) || storeRequester;
    const lojaSolicitante = getStoreLabel(normalizedRequesterValue);
    const labelISO = coerceISODateString(receivedDate || orderDate);
    const listName = `Requisição - ${lojaSolicitante} - ${formatDateDDMMYY(labelISO)}`;

    try {
      const ok = await finalizeSession(currentSessionId, listName, true);
      if (ok) {
        await loadHistoryFromDatabase();
        setCurrentSessionId(null);
        setIsSessionMode(false);
        setAllItems([]);
        exitSession();
        toast.success(`Requisição "${listName}" enviada para a fila`);
        setIsLeaving(true);
        setTimeout(() => navigate('/requisicao-conclusao'), 180);
      }
    } catch (error) {
      handleError(error, { domain: 'requisicoes', operation: 'enviarParaFilaSessao', showToast: false });
      toast.error('Erro ao enviar requisição para a fila');
    }
    return;
  }

  // Fluxo sem sessão: salvar/atualizar requisição com status em_fila
  if (allItems.length === 0) {
    toast.error('Não há itens para enviar');
    return;
  }

  const normalizedRequesterValue = normalizeStoreName(storeRequester) || storeRequester;
  const lojaSolicitante = getStoreLabel(normalizedRequesterValue);
  const labelISO = coerceISODateString(receivedDate || orderDate);
  const listName = `Requisição - ${lojaSolicitante} - ${formatDateDDMMYY(labelISO)}`;

  try {
    const { data: { user } } = await supabase.auth.getUser();
    const currentUserId = user?.id || null;
    const normalizedPreparerValue = normalizeStoreName('Fábrica');
    const lojaPreparadora = getStoreLabel(normalizedPreparerValue) || 'Fábrica';
    const orderDateToSave = coerceISODateString(orderDate);
    const receivedDateToSave = coerceISODateString(receivedDate);
    if (currentRequisicaoId) {
      // Atualizar requisição existente com status em_fila (ou fallback)
      const { error: updateError } = await (supabase as any)
        .from('requisicoes')
        .update({
          nome: listName,
          solicitante: requesterName,
          preparador: preparerName,
          loja_solicitante: lojaSolicitante,
          loja_preparadora: lojaPreparadora,
          data_pedido: orderDateToSave,
          data_recebimento: receivedDateToSave,
          status: 'em_fila',
          enqueued_at: new Date().toISOString(),
          user_id: currentUserId,
          subtitle: requisitionSubtitle
        })
        .eq('id', currentRequisicaoId);

      if (updateError) {
        handleError(updateError, { domain: 'requisicoes', operation: 'atualizarRequisicao', showToast: false });
        toast.error('Erro ao atualizar requisição');
        return;
      }
      const categoryUpdates = allItems
        .map((item) => ({
          id: Number(item.id),
          category: getEffectiveCategory(item.manualCategory, item.category, String(item.name || '')) || detectCategory(String(item.name || ''))
        }))
        .filter((u) => Number.isFinite(u.id));
      for (const u of categoryUpdates) {
        await (supabase as any)
          .from('requisicoes_itens')
          .update({ category: u.category })
          .eq('id', u.id);
      }

      await loadHistoryFromDatabase();
      toast.success(`Requisição "${listName}" enviada para a fila`);

