// de maior score — então "chocolate" sob "Bolos no Pote" pontua mais alto para
// "Bolo no Pote Chocolate" do que para "Mini de Chocolate".
// IMPORTANTE: sempre usa o melhor produto encontrado (nunca rejeita). O controle
// de "revisar vs. travar" fica com shouldAutoLock — match incoerente com o título
// fica desbloqueado (não-isLocked), disparando o aviso do revisor, mas NÃO some
// de allItems (o que deixaria allItems vazio e impediria o Lançar).
if (!bestMatch) {
  const m = bestCatalogMatch({ name: item.name, category: item.category }, activeProducts);
  if (m.product) {
    bestScore = m.score;
    bestMatch = m.product; // sempre usa; shouldAutoLock só decide isLocked
  }
}

